def fit_logx(self, grid, n_boot=None, units=None, seed=None):
        """Fit the model in log-space."""
        if n_boot is None:
            n_boot = self.n_boot
        if units is None:
            units = self.units
        if seed is None:
            seed = self.seed

        X, y = np.c_[np.ones(len(self.x)), self.x], self.y
        grid = np.c_[np.ones(len(grid)), np.log(grid)]

        def reg_func(_x, _y):
            _x = np.c_[_x[:, 0], np.log(_x[:, 1])]
            return np.linalg.pinv(_x).dot(_y)

        yhat = grid.dot(reg_func(X, y))
        if self.ci is None:
            return yhat, None

        beta_boots = algo.regression_bootstrap(n_boot, units, seed,
                                               X, y, func=reg_func).T
        yhat_boots = grid.dot(beta_boots).T
        return yhat, yhat_boots

